<?php $title='Visão geral do sistema'; ?>
<div class="stat-grid"><?php foreach(['users'=>'Usuários','pets'=>'Pets','lost'=>'Casos ativos','partners'=>'Lojas sócias','tags'=>'Tags','scans'=>'Escaneamentos'] as $key=>$label):?><article class="stat-card"><span><?=e($label)?></span><strong><?=e($stats[$key])?></strong></article><?php endforeach;?></div>
<div class="dashboard-grid two"><section class="panel-card"><div class="section-row"><h2>Pets recentes</h2><a href="<?=url('/admin/pets')?>">Ver todos</a></div><?php foreach($recentPets as $pet):?><a class="admin-list-item" href="<?=url('/admin/pets/'.$pet['id'])?>"><div><b><?=e($pet['name'])?></b><small><?=e($pet['public_id'])?> · <?=e($pet['owner_email'])?></small></div><span class="status <?=$pet['is_lost']?'danger':'success'?>"><?=$pet['is_lost']?'PERDIDO':'ATIVO'?></span></a><?php endforeach;?></section><section class="panel-card"><div class="section-row"><h2>Lojas pendentes</h2><a href="<?=url('/admin/partners')?>">Gerenciar</a></div><?php foreach($pendingPartners as $partner):?><div class="admin-list-item"><div><b><?=e($partner['name'])?></b><small><?=e($partner['partner_type'])?></small></div><span class="status warning">PENDENTE</span></div><?php endforeach;?><?php if(!$pendingPartners):?><p class="muted">Nenhuma análise pendente.</p><?php endif;?></section></div>
<section class="dashboard-section"><h2>Auditoria recente</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ator</th><th>Ação</th><th>Entidade</th><th>ID</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['actor_name']?:'Sistema')?></td><td><?=e($log['action'])?></td><td><?=e($log['entity_type'])?></td><td><?=e($log['entity_id'])?></td></tr><?php endforeach;?></tbody></table></div></section>
